    [4743] = { name = "Seal of Ascension", level = 60, minLevel = 57, giver = "Scarshield Infiltrator", giverNpc = 10299, giverInside = "LBRS", turnIn = "Scarshield Infiltrator", turnInInside = "LBRS", zone = 1583, loot = { { item = 12324, name = "Forged Seal of Ascension", from = { { name = "Forged Seal of Ascension", npc = -175322 } } } }, objective = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken. It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!" },
