    [5251] = { name = "The Archivist", level = 60, minLevel = 55, giver = "Duke Nicholas Zverenhoff", giverNpc = 11039, turnIn = "Duke Nicholas Zverenhoff", turnInNpc = 11039, zone = 2017, kills = { { name = "Archivist Galford", inside = "STRAT_LIVE" } }, objective = "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive." },
