    [5282] = { name = "The Restless Souls", level = 60, minLevel = 55, giver = "Egan", giverNpc = 11140, turnIn = "Egan", turnInNpc = 11140, zone = 2017, kills = { { name = "Restless Soul", inside = "STRAT_LIVE" } }, objective = "Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs! Free 15 Restless Souls and return to Egan." },
    [5341] = { name = "Barov Family Fortune", level = 60, minLevel = 52, side = "Horde", giver = "Alexi Barov", giverNpc = 11022, turnIn = "Alexi Barov", turnInNpc = 11022, zone = 2057, loot = { { item = 13471, name = "The Deed to Brill", from = { { name = "The Deed to Brill", inside = "SCHOLOMANCE" } } }, { item = 13448, name = "The Deed to Caer Darrow", from = { { name = "The Deed to Caer Darrow", inside = "SCHOLOMANCE" } } }, { item = 13450, name = "The Deed to Southshore", from = { { name = "The Deed to Southshore", inside = "SCHOLOMANCE" } } }, { item = 13451, name = "The Deed to Tarren Mill", from = { { name = "The Deed to Tarren Mill", inside = "SCHOLOMANCE" } } } }, objective = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task." },
    [5342] = { name = "The Last Barov", level = 60, minLevel = 52, side = "Horde", giver = "Alexi Barov", giverNpc = 11022, turnIn = "Alexi Barov", turnInNpc = 11022, zone = 28, loot = { { item = 13469, name = "Head of Weldon Barov", from = { { name = "Weldon Barov", npc = 11023 } } } }, objective = "Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov. Be warned, Weldon will probably be well protected by Alliance scum." },
    [5343] = { name = "Barov Family Fortune", level = 60, minLevel = 52, side = "Alliance", giver = "Weldon Barov", giverNpc = 11023, turnIn = "Weldon Barov", turnInNpc = 11023, zone = 2057, loot = { { item = 13471, name = "The Deed to Brill", from = { { name = "The Deed to Brill", inside = "SCHOLOMANCE" } } }, { item = 13448, name = "The Deed to Caer Darrow", from = { { name = "The Deed to Caer Darrow", inside = "SCHOLOMANCE" } } }, { item = 13450, name = "The Deed to Southshore", from = { { name = "The Deed to Southshore", inside = "SCHOLOMANCE" } } }, { item = 13451, name = "The Deed to Tarren Mill", from = { { name = "The Deed to Tarren Mill", inside = "SCHOLOMANCE" } } } }, objective = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task." },
    [5344] = { name = "The Last Barov", level = 60, minLevel = 52, side = "Alliance", giver = "Weldon Barov", giverNpc = 11023, turnIn = "Weldon Barov", turnInNpc = 11023, zone = 28, loot = { { item = 13470, name = "Head of Alexi Barov", from = { { name = "Alexi Barov", npc = 11022 } } } }, objective = "Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov. Be warned, Alexi will probably be well protected by Horde filth." },
    [5382] = { name = "Doctor Theolen Krastinov, the Butcher", level = 60, minLevel = 55, giver = "Eva Sarkhoff", giverNpc = 11216, turnIn = "Eva Sarkhoff", turnInNpc = 11216, zone = 2057, kills = { { name = "Doctor Theolen Krastinov", inside = "SCHOLOMANCE" } }, named = { { name = "Lucien Sarkhoff", npc = 11217 } }, objective = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete." },
    [5384] = { name = "Kirtonos the Herald", level = 60, minLevel = 55, giver = "Eva Sarkhoff", giverNpc = 11216, turnIn = "Eva Sarkhoff", turnInNpc = 11216, zone = 2057, kills = { { name = "Kirtonos the Herald", inside = "SCHOLOMANCE" } }, objective = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul. Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff." },
    [5461] = { name = "The Human, Ras Frostwhisper", level = 60, minLevel = 57, giver = "Magistrate Marduke", giverNpc = 11286, turnIn = "Magistrate Marduke", turnInNpc = 11286, zone = 28, loot = { { item = 13585, name = "Keepsake of Remembrance", from = { { name = "Keepsake of Remembrance", npc = -176630 } } } }, objective = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke." },
