    [5464] = { name = "Menethil's Gift", level = 60, minLevel = 57, giverInside = "STRAT_LIVE", turnIn = "Leonid Barthalomew the Revered", turnInNpc = 11036, zone = 139, objective = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands." },
