    [5515] = { name = "Krastinov's Bag of Horrors", level = 60, minLevel = 55, giver = "Eva Sarkhoff", giverNpc = 11216, turnIn = "Eva Sarkhoff", turnInNpc = 11216, zone = 2057, loot = { { item = 13725, name = "Krastinov's Bag of Horrors", from = { { name = "Jandice Barov", inside = "SCHOLOMANCE" } } } }, objective = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff." },
