    [7508] = { name = "The Forging of Quel'Serrar", level = 60, minLevel = 60, classes = { "WARRIOR", "PALADIN" }, startItem = "A Dull and Flat Elven Blade", startItemId = 18513, turnIn = "Lorekeeper Lydros", turnInInside = "DM_NORTH", zone = 2557, objective = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros." },
    [7509] = { name = "The Forging of Quel'Serrar", level = 60, minLevel = 60, classes = { "WARRIOR", "PALADIN" }, giver = "Lorekeeper Lydros", giverNpc = 14368, giverInside = "DM_NORTH", turnIn = "Lorekeeper Lydros", turnInInside = "DM_NORTH", zone = 2159, kills = { { name = "Onyxia", inside = "ONYXIA" } }, loot = { { item = 18492, name = "Treated Ancient Blade", from = {  } } }, objective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence. The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse. Do this and Quel'Serrar will be yours." },
    [7563] = { name = "Rage of Blood", level = 58, minLevel = 60, classes = { "WARLOCK" }, giver = "Mor'zul Bloodbringer", giverNpc = 14436, turnIn = "Mor'zul Bloodbringer", turnInNpc = 14436, loot = { { item = 18590, name = "Raging Beast's Blood", from = { { name = "Berserk Owlbeast", npc = 7454 }, { name = "Crazed Owlbeast", npc = 7452 } } } }, objective = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes." },
    [7564] = { name = "Wildeyes", level = 58, minLevel = 60, classes = { "WARLOCK" }, giver = "Mor'zul Bloodbringer", giverNpc = 14436, turnIn = "Gorzeeki Wildeyes", turnInNpc = 14437, objective = "Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes." },
    [7581] = { name = "The Prison's Bindings", level = 60, minLevel = 60, classes = { "WARLOCK" }, giver = "Daio the Decrepit", giverNpc = 14463, turnIn = "Daio the Decrepit", turnInNpc = 14463, loot = { { item = 18603, name = "Satyr Blood", from = { { name = "Wildspawn Betrayer", inside = "DM_EAST" }, { name = "Wildspawn Felsworn", inside = "DM_EAST" } } } }, named = { { name = "Wildspawn Satyr", inside = "DM_EAST" } }, objective = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done." },
    [7582] = { name = "The Prison's Casing", level = 60, minLevel = 60, classes = { "WARLOCK" }, giver = "Daio the Decrepit", giverNpc = 14463, turnIn = "Daio the Decrepit", turnInNpc = 14463, loot = { { item = 18604, name = "Tears of the Hederine", from = { { name = "Ridolus" }, { name = "Hederine Initiate", npc = 7461 } } } }, objective = "Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task." },
    [7583] = { name = "Suppression", level = 60, minLevel = 60, classes = { "WARLOCK" }, giver = "Daio the Decrepit", giverNpc = 14463, turnIn = "Daio the Decrepit", turnInNpc = 14463, loot = { { item = 18605, name = "Imprisoned Doomguard", from = { { name = "Imprisoned Doomguard", npc = -179644 } } } }, named = { { name = "Doomguard Commander", npc = 12396 } }, objective = "Venture forth into the Tainted Scar and locate a Doomguard Commander. Use the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture. Should you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar." },
    [7601] = { name = "What Niby Commands", level = 50, minLevel = 50, classes = { "WARLOCK" }, giver = "Niby the Almighty", giverNpc = 14469, turnIn = "Impsy", turnInNpc = 14470, objective = "Speak with Impsy in Felwood." },
    [7602] = { name = "Flawless Fel Essence", level = 55, minLevel = 50, classes = { "WARLOCK" }, giver = "Impsy", giverNpc = 14470, turnIn = "Impsy", turnInNpc = 14470, loot = { { item = 18624, name = "Flawless Fel Essence (Azshara)", from = { { name = "Legashi Blackguard" }, { name = "Legashi Hellraiser" } } }, { item = 18622, name = "Flawless Fel Essence (Jaedenar)", from = { { name = "Jaedenar Legionnaire", npc = 9862 } } }, { item = 18623, name = "Flawless Fel Essence (Dark Portal)", from = { { name = "Felguard Sentry", npc = 6011 } } } }, named = { { name = "Legashi Satyr", npc = 6200 } }, objective = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations. The Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region. Recover the Flawless Fel Essences and return to Impsy in Felwood." },
    [7603] = { name = "Kroshius' Infernal Core", level = 55, minLevel = 50, classes = { "WARLOCK" }, giver = "Impsy", giverNpc = 14470, turnIn = "Niby the Almighty", turnInNpc = 14469, kills = { { name = "Kroshius", npc = 14467 } }, loot = { { item = 18625, name = "Kroshius' Infernal Core", from = { { name = "Kroshius", npc = 14467 } } } }, objective = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core. Return Kroshius' Infernal Core to Niby the Almighty in Felwood." },
    [7623] = { name = "Lord Banehollow", level = 58, minLevel = 60, classes = { "WARLOCK" }, giver = "Gorzeeki Wildeyes", giverNpc = 14437, turnIn = "Lord Banehollow", turnInNpc = 9516, objective = "Purchase Shadowy Potions from Gorzeeki in the Burning Steppes. Use the potions to travel through Jaedenar, and speak with Lord Banehollow." },
    [7624] = { name = "Ulathek the Traitor", level = 58, minLevel = 60, classes = { "WARLOCK" }, giver = "Lord Banehollow", giverNpc = 9516, turnIn = "Lord Banehollow", turnInNpc = 9516, loot = { { item = 18719, name = "The Traitor's Heart", from = { { name = "Ulathek", npc = 14523 } } } }, objective = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar." },
