    [7629] = { name = "Imp Delivery", level = 60, minLevel = 60, classes = { "WARLOCK" }, giver = "Gorzeeki Wildeyes", giverNpc = 14437, turnIn = "Gorzeeki Wildeyes", turnInNpc = 14437, kills = { { name = "J'eevee", inside = "SCHOLOMANCE" } }, objective = "Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes." },
    [7630] = { name = "Arcanite", level = 60, minLevel = 60, classes = { "WARLOCK" }, giver = "Gorzeeki Wildeyes", giverNpc = 14437, turnIn = "Gorzeeki Wildeyes", turnInNpc = 14437, loot = { { item = 12360, name = "Arcanite Bar", from = {  } } }, objective = "Bring 3 Arcanite Bar to Gorzeeki in the Burning Steppes." },
