    [7632] = { name = "The Ancient Leaf", level = 60, minLevel = 60, classes = { "HUNTER" }, giver = "Majordomo Executus", giverNpc = 12018, turnIn = "Vartrus the Ancient", turnInNpc = 14524, objective = "Find the owner of the Ancient Petrified Leaf. Good luck, <Name>; It's a big world." },
