    [7635] = { name = "A Proper String", level = 60, minLevel = 60, classes = { "HUNTER" }, giver = "Stoma the Ancient", giverNpc = 14525, turnIn = "Stoma the Ancient", turnInNpc = 14525, loot = { { item = 18705, name = "Mature Black Dragon Sinew", from = { { name = "Onyxia", inside = "ONYXIA" } } } }, objective = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood." },
    [7636] = { name = "Stave of the Ancients", level = 60, minLevel = 60, classes = { "HUNTER" }, giver = "Vartrus the Ancient", giverNpc = 14524, turnIn = "Vartrus the Ancient", turnInNpc = 14524, loot = { { item = 18952, name = "Simone's Head", from = { { name = "Simone the Seductress" } } }, { item = 18953, name = "Klinfran's Head", from = { { name = "Klinfran the Crazed" } } }, { item = 18954, name = "Solenor's Head", from = { { name = "Solenor the Slayer" } } }, { item = 18955, name = "Artorius's Head", from = { { name = "Artorius the Doombringer" } } } }, objective = "You must find and destroy these four demonic corrupters: Simone the Seductress. Klinfran the Crazed. Solenor the Slayer. Artorius the Doombringer. Destroy these creatures and return to Vartrus the Ancient in Felwood with their heads. Refer to the Petrified Bark in your inventory for clues as to their whereabouts. You MUST complete this task by yourself." },
    [7637] = { name = "Emphasis on Sacrifice", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "Lord Grayson Shadowbreaker", giverNpc = 928, turnIn = "High Priest Rohan", turnInNpc = 11406, objective = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it." },
    [7638] = { name = "Lord Grayson Shadowbreaker", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "Duthorian Rall", giverNpc = 6171, turnIn = "Lord Grayson Shadowbreaker", turnInNpc = 928, objective = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District." },
    [7639] = { name = "To Show Due Judgment", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "High Priest Rohan", giverNpc = 11406, turnIn = "Lord Grayson Shadowbreaker", turnInNpc = 928, objective = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." },
    [7640] = { name = "Exorcising Terrordale", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "Lord Grayson Shadowbreaker", giverNpc = 928, turnIn = "Lord Grayson Shadowbreaker", turnInNpc = 928, kills = { { name = "Terrordale Spirit", npc = 14564 } }, objective = "Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." },
    [7641] = { name = "The Work of Grimand Elmore", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "Lord Grayson Shadowbreaker", giverNpc = 928, turnIn = "Grimand Elmore", turnInNpc = 1416, objective = "Speak with Grimand Elmore in Stormwind's Dwarven District." },
    [7642] = { name = "Collection of Goods", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "Grimand Elmore", giverNpc = 1416, turnIn = "Grimand Elmore", turnInNpc = 1416, loot = { { item = 13180, name = "Stratholme Holy Water", from = { { name = "Supply Crate", inside = "STRAT_LIVE" }, { name = "Stratholme Supply Crate", inside = "STRAT_LIVE" } } }, { item = 8836, name = "Arthas' Tears", from = { { name = "Arthas' Tears", inside = "RAZORFEN_DOWNS" } } }, { item = 14047, name = "Runecloth", from = { { name = "Heavy Fel Iron Chest" }, { name = "Adamantite Bound Chest" } } }, { item = 12360, name = "Arcanite Bar", from = {  } } }, objective = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind." },
    [7643] = { name = "Ancient Equine Spirit", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "Lord Grayson Shadowbreaker", giverNpc = 928, turnIn = "Ancient Equine Spirit", turnInInside = "DM_WEST", loot = { { item = 18775, name = "Manna-Enriched Horse Feed", from = {  } } }, named = { { name = "Merideth Carlson", npc = 2357 }, { name = "Tendris Warpwood", inside = "DM_WEST" } }, objective = "Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food. Travel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it." },
    [7644] = { name = "Blessed Arcanite Barding", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "Ancient Equine Spirit", giverNpc = 14566, giverInside = "DM_WEST", turnIn = "Lord Grayson Shadowbreaker", turnInNpc = 928, objective = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." },
    [7646] = { name = "The Divination Scryer", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "Lord Grayson Shadowbreaker", giverNpc = 928, turnIn = "Lord Grayson Shadowbreaker", turnInNpc = 928, loot = { { item = 12800, name = "Azerothian Diamond", from = { { name = "Cliff Breaker", npc = 6146 }, { name = "Anubisath Guardian", inside = "AQ20" } } }, { item = 18335, name = "Pristine Black Diamond", from = {  } } }, objective = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." },
    [7647] = { name = "Judgment and Redemption", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "Lord Grayson Shadowbreaker", giverNpc = 928, turnIn = "Darkreaver's Fallen Charger", turnInInside = "SCHOLOMANCE", loot = { { item = 18799, name = "Charger's Redeemed Soul", from = {  } }, { item = 18792, name = "Blessed Arcanite Barding", from = { { name = "Petrified Treant", inside = "DM_EAST" }, { name = "Risen Construct", inside = "SCHOLOMANCE" } } } }, named = { { name = "Death Knight Darkreaver", inside = "SCHOLOMANCE" } }, objective = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger. Give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger." },
    [7648] = { name = "Grimand's Finest Work", level = 60, minLevel = 60, side = "Alliance", classes = { "PALADIN" }, giver = "Grimand Elmore", giverNpc = 1416, turnIn = "Lord Grayson Shadowbreaker", turnInNpc = 928, objective = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection." },
