    [8257] = { name = "Blood of Morphaz", level = 52, minLevel = 50, classes = { "PRIEST" }, giver = "Ogtinc", giverNpc = 8405, turnIn = "Greta Mosshoof", turnInNpc = 10922, kills = { { name = "Morphaz", inside = "SUNKEN_TEMPLE" } }, loot = { { item = 20025, name = "Blood of Morphaz", from = { { name = "Morphaz", inside = "SUNKEN_TEMPLE" } } } }, objective = "Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows." },
    [8258] = { name = "The Darkreaver Menace", level = 60, minLevel = 60, side = "Horde", classes = { "SHAMAN" }, giver = "Sagorne Creststrider", giverNpc = 13417, turnIn = "Sagorne Creststrider", turnInNpc = 13417, loot = { { item = 18880, name = "Darkreaver's Head", from = { { name = "Death Knight Darkreaver", inside = "SCHOLOMANCE" } } } }, objective = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him. Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar." },
    [8304] = { name = "Dearest Natalia", level = 60, minLevel = 58, giver = "Commander Mar'alith", giverNpc = 15181, turnIn = "Commander Mar'alith", turnInNpc = 15181, zone = 1377, kills = { { name = "Frankal Stonebridge", npc = 15171 }, { name = "Rutgar Glyphshaper", npc = 15170 } }, objective = "Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold. Once you have gathered the requested information, return to Commander Mar'alith." },
    [8309] = { name = "Glyph Chasing", level = 60, minLevel = 58, giver = "Rutgar Glyphshaper", giverNpc = 15170, turnIn = "Rutgar Glyphshaper", turnInNpc = 15170, zone = 1377, loot = { { item = 20455, name = "Hive'Ashi Rubbing", from = { { name = "Hive'Ashi Glyphed Crystal", npc = -180454 } } }, { item = 20454, name = "Hive'Zora Rubbing", from = { { name = "Hive'Zora Glyphed Crystal", npc = -180455 } } }, { item = 20456, name = "Hive'Regal Rubbing", from = { { name = "Hive'Regal Glyphed Crystal" } } } }, objective = "Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive. Use the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task." },
    [8310] = { name = "Breaking the Code", level = 60, minLevel = 58, giver = "Frankal Stonebridge", giverNpc = 15171, turnIn = "Frankal Stonebridge", turnInNpc = 15171, zone = 1377, loot = { { item = 20457, name = "Hive'Ashi Silithid Brain", from = { { name = "Hive'Ashi Ambusher", npc = 13301 }, { name = "Hive'Ashi Defender", npc = 11722 } } }, { item = 20458, name = "Hive'Zora Silithid Brain", from = { { name = "Hive'Zora Hive Sister", npc = 11729 }, { name = "Hive'Zora Reaver", npc = 11728 } } }, { item = 20459, name = "Hive'Regal Silithid Brain", from = { { name = "Hive'Regal Ambusher", npc = 11730 }, { name = "Hive'Regal Burrower", npc = 11731 } } } }, objective = "Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task." },
    [8314] = { name = "Unraveling the Mystery", level = 60, minLevel = 58, giver = "Rutgar Glyphshaper", giverNpc = 15170, turnIn = "Geologist Larksbane", turnInNpc = 15183, zone = 1377, objective = "Rutgar Glyphshaper at Bronzebeard's Encampment wants you to deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus." },
    [8315] = { name = "The Calling", level = 60, minLevel = 58, giver = "Geologist Larksbane", giverNpc = 15183, turnIn = "Geologist Larksbane", turnInNpc = 15183, zone = 1377, loot = { { item = 20465, name = "Crystal Unlocking Mechanism", from = { { name = "Emissary Roman'khan", npc = 14862 } } } }, objective = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary. You have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed. Assemble an army for this task, <Name>!" },
